	"com/fsoft/zpmmaintenancecockpit/view/fragment/AssignTechnicianDialog.fragment.xml":'<core:FragmentDefinition xmlns="sap.m" xmlns:core="sap.ui.core"><SelectDialog id="assignTechnicianDialog"\n        title="{i18n>orderDetailTechnicianAssignTitle}"\n        items="{techCatalog>/}"\n        confirm=".onConfirmAssignTechnician"\n        cancel=".onCancelAssignTechnician"\n        search=".onSearchAssignTechnician"\n        noDataText="{i18n>orderDetailTechnicianAssignNoData}"><StandardListItem\n            title="{techCatalog>key} — {techCatalog>name}"\n            description="{techCatalog>skill} · {techCatalog>workCenter}"\n            info="{techCatalog>available}"\n            infoState="{\n                path: \'techCatalog>available\',\n                formatter: \'.formatter.formatAvailableState\'\n            }"\n            type="Active" /></SelectDialog></core:FragmentDefinition>\n',
